import { useState } from 'react';

const [passwordVisibility, setPasswordVisibility] = useState("text");

export default function MainPage(){
  return <div id="mainContainer"> 
          <form>
            <input type="text" id="userName" placeholder="Username"></input>
            <input type={passwordVisibility} id="password" placeholder="Password"></input>
            <button id="passWordVisibilityChange" onClick={changeVisibilityOfPassword()}></button>
            <input type="submit"></input>
          </form>
        </div>
}

function changeVisibilityOfPassword(){
  if(passwordVisibility === "text"){
    setPasswordVisibility("password");
  }else{
    setPasswordVisibility("text");
  }
}
